import {assertJson,parseJsonStrict,validateSchema,assertSchema,validateOperationConfig,errorEnvelope,assertFittedPipeline,CONTRACT_VERSION} from '../../packages/contracts/src/index.mjs';
import {canonicalJson,hashCanonical,hashBytes,mutationHash,encodeTable,decodeTable,encodeCSR,decodeCSR,encodeLineage,decodeLineage} from '../../packages/data-format/src/index.mjs';
import {registry,getOperation,requireAvailable} from '../../packages/operation-registry/src/index.mjs';
export const id=n=>'00000000-0000-4000-8000-'+n.toString(16).padStart(12,'0');
const check=(v,m)=>{if(!v)throw Error(m);};
const same=(a,b)=>check(JSON.stringify(a)===JSON.stringify(b),'Values differ');
function rejects(fn,code){try{fn();throw Error('not rejected');}catch(e){check(e.code===code,'Expected '+code+', got '+(e.code??e.message));return true;}}
async function rejectsAsync(fn,code){try{await fn();throw Error('not rejected');}catch(e){check(e.code===code,'Expected '+code+', got '+(e.code??e.message));return true;}}
export function tableFixture(){const types=['string','number','boolean','date','datetime','bigint','decimal','json','string'];const columns=types.map((logicalType,i)=>({columnId:id(100+i),name:i===0?'Tiếng Việt':logicalType,logicalType,nullable:true,sourceColumns:[]}));const rows=[{rowId:id(1),cells:['Tiếng Việt 😀\n"x",y',1.25,true,'2024-02-29','2026-11-02T00:00:00.123456Z','9007199254740993','123456789012345678.123456789','[1,{"x":"đ"}]','null']},{rowId:id(2),cells:['',null,false,'2026-11-02','2026-11-02T00:00:00Z','-9007199254740993','0.000000001','{"array":[1,2]}',null]}];return{columns,rows};}
export async function runB020Checks(){
const tests=[];const test=async(id,expected,fn)=>{try{tests.push({id,expected,status:'passed',actual:await fn()});}catch(e){tests.push({id,expected,status:'failed',actual:{message:e.message,code:e.code}});}};
await test('B020-canonical-X01-replay','Exact X01 canonical fixture/hash; no numeric/surrogate coercion',async()=>{const v={z:3,a:{'ế':'Tiếng Việt',b:[true,null,'null',-0,1e-7]}},expected='{"a":{"b":[true,null,"null",0,1e-7],"ế":"Tiếng Việt"},"z":3}';check(canonicalJson(v)===expected,'RFC bytes');const sha=await hashCanonical(v);check(sha==='7921516a892fd931ddad5f2ecaf4a351d259832f84c7c170f76a99825f8d8865','RFC hash');for(const x of [NaN,Infinity,undefined,1n,9007199254740992,'\ud800'])rejects(()=>assertJson(x),'VALIDATION_FAILED');return{canonical:expected,sha256:sha,invalidRejected:6,contract:CONTRACT_VERSION};});
await test('B020-strict-JSON','Reject duplicate escaped keys/raw unsafe integer/nonJSON objects/cycles/getters/sparse arrays; allow shared references',()=>{for(const text of ['{"n":9007199254740993}','{"a":1,"\\u0061":2}','{"n":1e999}','{"n":undefined}'])rejects(()=>parseJsonStrict(text),'VALIDATION_FAILED');const cycle={};cycle.self=cycle;for(const value of [cycle,new Date(),Array(2),Object.defineProperty({},'x',{get(){throw Error('getter executed');},enumerable:true})])rejects(()=>assertJson(value),'VALIDATION_FAILED');const shared={a:1};assertJson([shared,shared]);rejects(()=>parseJsonStrict('['.repeat(130)+']'.repeat(130)),'RESOURCE_LIMIT_EXCEEDED');same(parseJsonStrict('{"text":"a\\\\b \\" quoted","n":1.25}'),{text:'a\\b " quoted',n:1.25});return{duplicateKeysAndUnsafeRawRejected:true,noGetterExecution:true,depthLimit:128};});
await test('B020-schema-error-boundaries','Unknown fields rejected; lifecycle states not API errors; no raw value/secret detail; schema dialect is shared',()=>{const good=errorEnvelope('VALIDATION_FAILED','req-123',{path:'/cells/0',scope:'field'},false);check(validateSchema('error-envelope.json',good).valid,'good error invalid');check(!validateSchema('error-envelope.json',{...good,secret:'bad'}).valid,'unknown extra');rejects(()=>errorEnvelope('VALIDATION_FAILED','req',{value:'raw row'}),'VALIDATION_FAILED');rejects(()=>errorEnvelope('AI_REQUEST_UNKNOWN','req'),'VALIDATION_FAILED');rejects(()=>assertSchema('column.json',{columnId:id(1),name:'x',logicalType:'number',nullable:false,sourceColumns:[],extra:true}),'VALIDATION_FAILED');return{envelope:good,unknownFieldsRejected:true,lifecycleErrorRejected:true};});
await test('B020-table-roundtrip','Typed precision/null/empty/JSON/unicode/date/row-column IDs and source bytes preserved; chunk boundaries whole records',async()=>{const {columns,rows}=tableFixture(),source=new TextEncoder().encode('tên,số\r\n"Tiếng Việt",1\r\n'),sourceHash=await hashBytes(source);const encoded=await encodeTable(rows,columns,{chunkTargetBytes:80});same(await decodeTable(encoded.manifest,encoded.chunks),rows);check(encoded.chunks.length===2&&encoded.chunks.every(c=>new TextDecoder().decode(c.bytes).endsWith('\n')),'record split');check(await hashBytes(source)===sourceHash,'source changed');return{rowIds:rows.map(r=>r.rowId),columnIds:encoded.manifest.columnOrder,sourceHash,chunkSizes:encoded.chunks.map(c=>c.bytes.length),manifestHash:await hashCanonical(encoded.manifest),precision:rows[0].cells.slice(5,7)};});
await test('B020-table-invalid-bytes-manifest','Hash/cell/column order/rowcount/date/nullability/duplicate IDs/UTF8/BOM failure keeps input unchanged',async()=>{const {columns,rows}=tableFixture(),e=await encodeTable(rows,columns),badBytes=e.chunks.map(c=>({...c,bytes:c.bytes.slice()}));badBytes[0].bytes[0]^=1;await rejectsAsync(()=>decodeTable(e.manifest,badBytes),'HASH_MISMATCH');const shape=structuredClone(e.manifest);shape.rowCount++;await rejectsAsync(()=>decodeTable(shape,e.chunks),'VALIDATION_FAILED');const order=structuredClone(e.manifest);order.columnOrder.reverse();await rejectsAsync(()=>decodeTable(order,e.chunks),'VALIDATION_FAILED');for(const change of [r=>({...r,rowId:'label-V1'}),r=>({...r,cells:r.cells.slice(1)}),r=>({...r,cells:r.cells.map((v,i)=>i===3?'2026-02-30':v)})])await rejectsAsync(()=>encodeTable([change(rows[0])],columns),'VALIDATION_FAILED');await rejectsAsync(()=>encodeTable([rows[0],rows[0]],columns),'VALIDATION_FAILED');const nonNull=structuredClone(columns);nonNull[1].nullable=false;await rejectsAsync(()=>encodeTable(rows,nonNull),'VALIDATION_FAILED');const one=await encodeTable([rows[0]],columns),b=new Uint8Array([239,187,191,...one.chunks[0].bytes]),bom=structuredClone(one.manifest);bom.chunks[0].sha256=await hashBytes(b);bom.chunks[0].sizeBytes=b.length;await rejectsAsync(()=>decodeTable(bom,[{artifactId:one.chunks[0].artifactId,bytes:b}]),'VALIDATION_FAILED');return{rejected:9,sourceRowsStillValid:JSON.stringify(rows)===JSON.stringify(tableFixture().rows)};});
await test('B020-CSR-LE-sparse','Exact little-endian indptr/indices/float64 bytes, 2x4 sparse nnz3, mapping preserved, no dense output',async()=>{const csr={rows:2,cols:4,indptr:[0,2,3],indices:[0,3,1],data:[1,2.5,-4]},mapping=Array.from({length:4},(_,i)=>({columnId:id(200+i),sourceColumns:[]}));const e=await encodeCSR(csr,[id(1),id(2)],mapping),decoded=await decodeCSR(e.manifest,e.buffers);same({...csr,rowIds:[id(1),id(2)],featureMapping:mapping},decoded);const hex=b=>[...b].map(v=>v.toString(16).padStart(2,'0')).join('');check(hex(e.buffers[0].bytes)==='000000000200000003000000','indptrLE');check(hex(e.buffers[2].bytes)==='000000000000f03f000000000000044000000000000010c0','float64LE');await rejectsAsync(()=>encodeCSR({...csr,indices:[0,4,1]},[id(1),id(2)],mapping),'VALIDATION_FAILED');const bad=e.buffers.map(b=>({...b,bytes:b.bytes.slice()}));bad[2].bytes[0]^=1;await rejectsAsync(()=>decodeCSR(e.manifest,bad),'HASH_MISMATCH');return{shape:[2,4],nnz:3,bufferSizes:e.buffers.map(b=>b.bytes.length),dataHex:hex(e.buffers[2].bytes),denseOutputPresent:Object.hasOwn(e,'dense'),scope:'Format supports sparse; no engine sparse solve claimed'};});
await test('B020-lineage-multiple-sources','Ordered dataset/version/row refs survive JSONL, left-unmatched has no right ref; IDs independent of labels',()=>{const source=(rowId,role,sourceOrder)=>({datasetId:id(role==='left'?10:11),versionId:id(role==='left'?20:21),rowId,role,sourceOrder});const rows=[{rowId:id(500),sources:[source(id(1),'left',0),source(id(3),'right',1)]},{rowId:id(501),sources:[source(id(2),'left',0)]}];const bytes=encodeLineage(rows);same(decodeLineage(bytes),rows);rejects(()=>encodeLineage([rows[0],rows[0]]),'VALIDATION_FAILED');return{rows,scope:'Serializer oracle, not a join executor'};});
await test('B020-registry-one-config-per-id','All145 IDs retained; oneversionedschema perID; no executor/schema/capability enabled by placeholder',()=>{check(registry.operations.length===145&&new Set(registry.operations.map(o=>o.id)).size===145,'coverage');for(const op of registry.operations){assertSchema('operation-definition.json',op);check(op.executor===null&&op.capability.status==='unavailable'&&!op.offlineCapable,'enabled placeholder');rejects(()=>validateOperationConfig({operationId:op.id,configVersion:1,columnIds:[],params:{}}),'UNSUPPORTED_OPERATION');rejects(()=>requireAvailable(op.id),'UNSUPPORTED_OPERATION');}const pretend=structuredClone(registry.operations[0]);pretend.capability.status='available';check(!validateSchema('operation-definition.json',pretend).valid,'placeholder enabled without handlers/evidence');check(getOperation('VIEW3D.SAVE_LOCAL_CAMERA')?.outputKind==='config','camera output differs');rejects(()=>validateOperationConfig({operationId:'MODEL.UNKNOWN',configVersion:1,columnIds:[],params:{}}),'VALIDATION_FAILED');return{operations:145,unavailable:145,configSchemasRejectUntilImplemented:145};});
await test('B020-metric-fit-scope','Defined finite metric; undefined null+reason; supervised rejects full-fit learned step, PCAfull allowed',()=>{const ref={datasetId:id(10),versionId:id(20)},metric={name:'r2',value:null,status:'undefined',reason:'constant test target',evaluationSet:'test',params:{},sourceRefs:[ref]};assertSchema('metric-record.json',metric);const noReason={...metric};delete noReason.reason;check(!validateSchema('metric-record.json',noReason).valid,'missingreason');check(!validateSchema('metric-record.json',{...metric,status:'defined'}).valid,'definednull');const p={schemaVersion:1,orderedSteps:[{operationId:'PREP.STANDARD',configVersion:1,fitScope:'full',learnedArtifactRefs:[]}],featureOrder:[id(100)],sourceRefs:[ref],engineVersion:'fixture',serializerVersion:'fixture-v1',missingPolicy:'error',unknownPolicy:'error'};assertFittedPipeline(p);rejects(()=>assertFittedPipeline(p,{supervised:true}),'VALIDATION_FAILED');p.orderedSteps[0].fitScope='train';assertFittedPipeline(p,{supervised:true});return{undefinedReasonRequired:true,supervisedFullFitRejected:true,fullFitUnsupervisedAllowed:true};});
await test('B020-business-mutation-hash','Exact documented business fields only; transport mutationID/payloadHash excluded; payload/revision/ordereddependencies affecthash',async()=>{const m={mutationId:id(80),kind:'project.rename',projectId:id(10),entityId:id(10),schemaVersion:1,baseRevision:2,dependencies:[],payload:{name:'Tiếng Việt'},payloadHash:'0'.repeat(64)},h=await mutationHash(m);check(h===await mutationHash({...m,mutationId:id(81),payloadHash:'a'.repeat(64)}),'transport fields inhash');check(h!==await mutationHash({...m,baseRevision:3}),'revision ignored');check(h!==await mutationHash({...m,payload:{name:'khác'}}),'payload ignored');return{sha256:h,algorithm:CONTRACT_VERSION.canonicalHash,fields:['schemaVersion','kind','entityId','projectId','baseRevision','dependencies','payload','artifacts'],mutationIdExcluded:true};});
return tests;
}
